/* Central da Fiel — Jogos v2. Design próprio, dados da integração existente. */
const fielEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fielTime=s=>{const d=new Date(s);return Number.isFinite(+d)?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(d):'Data a confirmar'};
const fielDate=s=>{const d=new Date(s);return Number.isFinite(+d)?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'short',year:'numeric'}).format(d):'Data a confirmar'};
const fielCrests={
'corinthians':'/assets/escudo.webp',
'são paulo':'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A3o_Paulo_Futebol_Clube_logo_%282022%29.svg',
'botafogo':'https://commons.wikimedia.org/wiki/Special:FilePath/Botafogo_de_Futebol_e_Regatas_logo.svg',
'atlético-mg':'https://commons.wikimedia.org/wiki/Special:FilePath/Clube_Atl%C3%A9tico_Mineiro_logo.svg',
'grêmio':'https://commons.wikimedia.org/wiki/Special:FilePath/Gr%C3%AAmio_FBPA_logo.svg',
'remo':'https://commons.wikimedia.org/wiki/Special:FilePath/Clube_do_Remo_logo.svg'
};
function fielCrest(name){const key=String(name||'').toLocaleLowerCase('pt-BR').trim();const url=fielCrests[key];return url?'<img class="fiel-crest" src="'+url+'" alt="Escudo do '+fielEscape(name)+'" loading="lazy" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'grid\'"><span class="fiel-crest-fallback" style="display:none">'+fielEscape(String(name).split(' ').map(x=>x[0]).slice(0,3).join(''))+'</span>':'<span class="fiel-crest-fallback">'+fielEscape(String(name).split(' ').map(x=>x[0]).slice(0,3).join(''))+'</span>'}
function fielMatch(m,finished=false){const h=fielEscape(m.home||'A confirmar'),a=fielEscape(m.away||'A confirmar');const score=finished&&Number.isFinite(Number(m.homeScore))&&Number.isFinite(Number(m.awayScore))?'<span class="fiel-score">'+fielEscape(m.homeScore)+' <i>–</i> '+fielEscape(m.awayScore)+'</span>':'<span class="fiel-vs">VS</span>';const when=m.kickoff||m.date;const summary=finished&&m.summary?'<details class="fiel-summary"><summary>Como foi o jogo <span>⌄</span></summary><div class="fiel-summary-body"><p>'+fielEscape(m.summary)+'</p>'+(Array.isArray(m.highlights)?'<ul>'+m.highlights.map(t=>'<li>'+fielEscape(t)+'</li>').join('')+'</ul>':'')+'</div></details>':'';return '<article class="fiel-fixture"><div class="fiel-fixture-top"><span>'+fielEscape(m.competition||'Futebol masculino')+'</span><span>'+(m.round?'Rodada '+fielEscape(m.round):finished?'Encerrado':'Partida')+'</span></div><div class="fiel-teams"><div class="fiel-team"><div class="fiel-team-crest">'+fielCrest(m.home)+'</div><strong>'+h+'</strong></div>'+score+'<div class="fiel-team"><div class="fiel-team-crest">'+fielCrest(m.away)+'</div><strong>'+a+'</strong></div></div><div class="fiel-fixture-bottom"><span>◷ '+fielTime(when)+'</span><span>'+fielEscape(m.venue||'Local a confirmar')+'</span></div>'+summary+'</article>'}
function fielUpcoming(r){return (Array.isArray(r.upcoming)?r.upcoming:[r.nextMatch].filter(Boolean)).filter(m=>Number.isFinite(Date.parse(m.kickoff||m.date))&&Date.parse(m.kickoff||m.date)>Date.now()).sort((a,b)=>Date.parse(a.kickoff||a.date)-Date.parse(b.kickoff||b.date))}
function fielResults(r){return (Array.isArray(r.results)?r.results:[r.lastResult].filter(Boolean)).filter(m=>Number.isFinite(Date.parse(m.kickoff||m.date))&&Date.parse(m.kickoff||m.date)<=Date.now()).sort((a,b)=>Date.parse(b.kickoff||b.date)-Date.parse(a.kickoff||a.date))}
function renderSportsDetail(){const k=location.hash.slice(1),d=document.querySelector('#detail'),r=window.fielSports;if(!d||!['jogos','calendario','resultados','classificacao'].includes(k))return;
 const active=k==='resultados'?'resultados':k==='classificacao'?'classificacao':'jogos';const tab=(id,title)=>'<a href="#'+id+'" class="'+(active===id?'selected':'')+'" '+(active===id?'aria-current="page"':'')+'>'+title+'</a>';
 let content='';
 if(k==='classificacao'){const rows=window.fielSportsFresh&&Array.isArray(r?.standings)?r.standings:[];content=rows.length?'<div class="fiel-standing-wrap"><table class="fiel-standings"><thead><tr><th>Pos.</th><th>Clube</th><th>Pontos</th><th>Jogos</th></tr></thead><tbody>'+rows.map(t=>'<tr class="'+(t.isCorinthians?'ours':'')+'"><td>'+fielEscape(t.position)+'</td><td>'+fielEscape(t.name)+'</td><td>'+fielEscape(t.points)+'</td><td>'+fielEscape(t.played)+'</td></tr>').join('')+'</tbody></table></div>':'<div class="fiel-empty"><span>▤</span><h3>Classificação indisponível</h3><p>A tabela será exibida aqui quando a integração fornecer dados atualizados.</p></div>';}
 else{const finished=k==='resultados',matches=r?(finished?fielResults(r):fielUpcoming(r)):[];content=matches.length?'<div class="fiel-match-list">'+matches.map(m=>fielMatch(m,finished)).join('')+'</div>':'<div class="fiel-empty"><span>⚽</span><h3>'+(finished?'Resultados em atualização':'Ainda não há partidas futuras confirmadas')+'</h3><p>'+(finished?'Aguardando resultados verificados da integração.':'Assim que o calendário atualizado estiver disponível, os próximos confrontos aparecerão aqui, com adversário, data e estádio.')+'</p></div>';}
 const checked=r?.checkedAt?fielDate(r.checkedAt):'não disponível';d.innerHTML='<div class="fiel-games"><div class="fiel-games-head"><a href="#inicio" class="fiel-back">← Início</a><span class="fiel-kicker">CENTRAL DA FIEL / FUTEBOL MASCULINO</span><h2>Jogos do <em>Timão.</em></h2><p>O calendário, os resultados e a classificação em um só lugar.</p></div><nav class="fiel-tabs" aria-label="Navegação de jogos">'+tab('jogos','Próximos jogos')+tab('resultados','Resultados')+tab('classificacao','Classificação')+'</nav><div class="fiel-games-section"><div class="fiel-section-heading"><h3>'+(active==='jogos'?'Próximos confrontos':active==='resultados'?'Últimos resultados':'Brasileirão Série A')+'</h3><span class="fiel-update">Atualização: '+checked+'</span></div>'+content+'</div><p class="fiel-fineprint">Dados de referência da integração esportiva da Central da Fiel. Informações sujeitas a alterações; partidas e placares não são inventados quando a consulta está indisponível.</p></div>';window.scrollTo(0,0)}
function fielHome(r){const next=fielUpcoming(r)[0],last=fielResults(r)[0];const el=document.querySelector('.next'),lastEl=document.querySelector('.last');if(el){const p=el.querySelector('.pending');if(p)p.innerHTML=next?'<strong>'+fielEscape(next.home)+' × '+fielEscape(next.away)+'</strong><br>'+fielTime(next.kickoff||next.date)+'<br>'+fielEscape(next.venue||'Local a confirmar'):'<strong>Próximo jogo</strong><br>Calendário em atualização';const placeholder=el.querySelector('.placeholder,.opponent');if(placeholder)placeholder.textContent=next?(String(next.home).toLowerCase().includes('corinthians')?next.away:next.home):'A confirmar'}if(lastEl){const sc=lastEl.querySelector('.pending-score');if(sc)sc.textContent=last?last.home+' '+last.homeScore+' × '+last.awayScore+' '+last.away:'Resultados em atualização';const p=lastEl.querySelector('.small');if(p)p.textContent=last?fielDate(last.kickoff||last.date)+' · '+(last.competition||'Futebol masculino'):'Aguardando consulta atualizada'}if(window.fielSportsFresh&&Array.isArray(r.standings)){const body=document.querySelector('.standing tbody');if(body)body.innerHTML=r.standings.map(t=>'<tr'+(t.isCorinthians?' style="background:#393020;font-weight:bold"':'')+'><td>'+fielEscape(t.position)+'</td><td>'+fielEscape(t.name)+'</td><td>'+fielEscape(t.points)+'</td><td>'+fielEscape(t.played)+'</td></tr>').join('')}}
window.addEventListener('hashchange',renderSportsDetail);
(async()=>{let r=null,live=false;try{const x=await fetch('/api/sports',{signal:AbortSignal.timeout(9000)});if(x.ok){const j=await x.json();if(j.mode==='api'&&Number.isFinite(Date.parse(j.checkedAt))&&Date.now()-Date.parse(j.checkedAt)<1200000){r=j;live=true}}}catch{}if(!r){try{const x=await fetch('/data/sports.json');if(x.ok)r=await x.json()}catch{}}window.fielSports=r;window.fielSportsFresh=live;if(r)fielHome(r);renderSportsDetail()})();
